BEGIN;
CREATE TABLE platform.module_batches(tenant_id uuid NOT NULL REFERENCES platform.tenants(id),batch_id uuid NOT NULL,endpoint_id uuid NOT NULL,agent_id uuid NOT NULL,installation_id text NOT NULL,first_sequence bigint NOT NULL,last_sequence bigint NOT NULL,event_count integer NOT NULL CHECK(event_count BETWEEN 1 AND 1000),content_sha256 text NOT NULL CHECK(content_sha256~'^[0-9a-f]{64}$'),received_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,batch_id));
CREATE TABLE platform.module_events(tenant_id uuid NOT NULL REFERENCES platform.tenants(id),event_id uuid NOT NULL,batch_id uuid NOT NULL,endpoint_id uuid NOT NULL,agent_id uuid NOT NULL,module_entity_id text NOT NULL,process_entity_id text,event_type text NOT NULL,sequence bigint NOT NULL CHECK(sequence>0),observed_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),ingested_at timestamptz NOT NULL DEFAULT now(),normalized_path text NOT NULL,basename text NOT NULL,image_type text NOT NULL,mode text NOT NULL,driver boolean NOT NULL,load_address numeric(20),sha256 text,signer_subject text,data_quality_flags text[] NOT NULL DEFAULT '{}',event_data jsonb NOT NULL,PRIMARY KEY(tenant_id,event_id),UNIQUE(tenant_id,endpoint_id,agent_id,sequence),FOREIGN KEY(tenant_id,batch_id) REFERENCES platform.module_batches(tenant_id,batch_id));
CREATE INDEX module_events_timeline ON platform.module_events(tenant_id,endpoint_id,observed_at DESC,event_id DESC);CREATE INDEX module_events_process ON platform.module_events(tenant_id,endpoint_id,process_entity_id,observed_at DESC);CREATE INDEX module_events_path ON platform.module_events(tenant_id,normalized_path,observed_at DESC);CREATE INDEX module_events_hash ON platform.module_events(tenant_id,sha256) WHERE sha256 IS NOT NULL;
CREATE TABLE platform.module_entities(tenant_id uuid NOT NULL REFERENCES platform.tenants(id),endpoint_id uuid NOT NULL,module_entity_id text NOT NULL,process_entity_id text,first_observed timestamptz NOT NULL,last_observed timestamptz NOT NULL,lifecycle text NOT NULL,latest_event jsonb NOT NULL,PRIMARY KEY(tenant_id,endpoint_id,module_entity_id));
CREATE TABLE platform.module_telemetry_health(tenant_id uuid NOT NULL REFERENCES platform.tenants(id),endpoint_id uuid NOT NULL,health_data jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,endpoint_id));
CREATE TABLE platform.module_policy_versions(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES platform.tenants(id),name text NOT NULL,version integer NOT NULL,policy jsonb NOT NULL,sha256 text NOT NULL,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),created_by text NOT NULL,UNIQUE(tenant_id,name,version));
CREATE TABLE platform.module_policy_assignments(tenant_id uuid NOT NULL REFERENCES platform.tenants(id),endpoint_id uuid,policy_id uuid NOT NULL REFERENCES platform.module_policy_versions(id),assigned_at timestamptz NOT NULL DEFAULT now(),assigned_by text NOT NULL,UNIQUE NULLS NOT DISTINCT(tenant_id,endpoint_id));
CREATE TABLE platform.module_policy_acknowledgements(tenant_id uuid NOT NULL REFERENCES platform.tenants(id),endpoint_id uuid NOT NULL,policy_id uuid NOT NULL,version integer NOT NULL,applied boolean NOT NULL,validation_error text,acknowledged_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,endpoint_id));
CREATE TABLE platform.module_export_jobs(tenant_id uuid NOT NULL REFERENCES platform.tenants(id),id uuid NOT NULL,created_by text NOT NULL,state text NOT NULL CHECK(state IN('pending','running','completed','failed','expired','cancelled')),format text NOT NULL CHECK(format IN('jsonl','csv')),query jsonb NOT NULL,fields text[] NOT NULL DEFAULT '{}',maximum_records integer NOT NULL CHECK(maximum_records BETWEEN 1 AND 10000),output_object_id uuid NOT NULL,manifest_object_id uuid NOT NULL,metadata_object_id uuid NOT NULL,record_count integer,output_size bigint,output_sha256 text,error_code text,error_summary text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,completed_at timestamptz,expires_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,id),UNIQUE(id));CREATE INDEX module_export_pending ON platform.module_export_jobs(created_at) WHERE state='pending';
COMMIT;
